(3) 入栈
int StackPush(SeqStack *S, DataType x)
/* 把数据元素值 x 压入顺序堆栈 S ,入栈成功则返回 1 ,
   否则返回 0 */
{ if(S->top >= MaxStackSize)
   {             printf(" 堆栈已满无法插入 ! \n");
          return 0;     }
   else {
                  S->stack[S->top] = x;
                  S->top ++;
               return 1; }
}

                                     18

(4) 出栈
int StackPop(SeqStack *S, DataType *d)
/* 弹出顺序堆栈 S 的栈顶数据元素值到参数 d ,出栈
   成功则返回 1 ,否则返回 0*/
{ if(S->top <= 0)
   {      printf(" 堆栈已空无数据元素出栈 ! \n");
   return 0;     }
   else {
           S->top --;
             *d = S->stack[S->top];
         return 1;    }
}
                                    19

(5) 取栈顶数据元素
int StackTop(SeqStack S, DataType *d)
/* 取顺序堆栈 S 的当前栈顶数据元素值到参数 d ,成
   功则返回 1 ,否则返回 0*/
{ if(S.top <= 0)
   {     printf(" 堆栈已空 ! \n");
         return 0;    }
   else {
             *d = S.stack[S.top - 1];
          return 1;
   }
}

