2 、链式堆栈的操作实现
(1)入栈
int StackPush(LSNode *head, DataType x)
{ LSNode *p;
    if((p = (LSNode *)malloc(sizeof(LSNode))) == NULL)
    { printf(" 内存空间不足无法插入 ! \n");
    return 0;     }
    p->data = x;
    p->next = head->next; /* 新结点链入栈顶 */
    head->next = p; /* 新结点成为新的栈顶 */
    return 1;
}
