(2) 出栈
int StackPop(LSNode *head, DataType *d)
{ LSNode *p = head->next;
   if(p == NULL)
   {      printf(" 堆栈已空出错! ");
   return 0;     }
   head->next = p->next; /* 删除原栈顶结点 */
   *d = p->data;          /* 原栈顶结点元素赋予 d*/
   free(p);          /* 释放原栈顶结点内存空间 */
   return 1;
}         注: 由此可以看出:一个链栈由其栈顶指针唯一指定
          设 head 指向栈顶元素,则 head=NULL 表示栈空

